<div class="row g-2 align-items-end mb-3" data-especialidad>
    <div class="col-12 col-md-5"><label class="form-label">Instrumento</label><select name="especialidades[<?= (int) $n ?>][id_instrumento]" data-especialidad-campo="id_instrumento" aria-label="Instrumento de la especialidad" class="form-select" required><option value="">Selecciona un instrumento</option><?php foreach ($instrumentos as $instrumento): ?><option value="<?= (int) $instrumento['id_instrumento'] ?>" <?= (string) ($esp['id_instrumento'] ?? '') === (string) $instrumento['id_instrumento'] ? 'selected' : '' ?>><?= $e($instrumento['nombre']) ?></option><?php endforeach; ?></select></div>
    <div class="col-6 col-md-3"><label class="form-label">Dominio</label><select name="especialidades[<?= (int) $n ?>][nivel_dominio]" data-especialidad-campo="nivel_dominio" aria-label="Nivel de dominio" class="form-select" required><?php foreach (\App\Application\Admin\InstructoresService::NIVELES as $nivel): ?><option value="<?= $nivel ?>" <?= ($esp['nivel_dominio'] ?? '') === $nivel ? 'selected' : '' ?>><?= ucfirst($nivel) ?></option><?php endforeach; ?></select></div>
